export const venues: Venue[] = venuesBase.map((v) => ({
  ...v,
  image: getManifestImageUrl(`venue:${v.slug}`) ?? v.image,
}));

export const getVenueBySlug = (slug: string) => venues.find((v) => v.slug === slug);
export const getVenuesByCity = (citySlug: string) =>
  venues.filter((v) => v.citySlug === citySlug);

export const getVenuesByNeighbourhood = (neighbourhoodSlug: string) =>
  venues.filter((v) => v.neighbourhoodSlug != null && v.neighbourhoodSlug === neighbourhoodSlug);
export const getVenuesByCategory = (category: string, citySlug?: string) =>
  venues.filter((v) => v.category === category && (!citySlug || v.citySlug === citySlug));
export const getNearbyVenues = (slug: string, limit = 4) => {
  const venue = getVenueBySlug(slug);
  if (!venue) return [];
  return venues
    .filter(
      (v) =>
        v.slug !== slug &&
        (venue.neighbourhoodSlug != null
          ? v.neighbourhoodSlug === venue.neighbourhoodSlug
          : v.citySlug === venue.citySlug)
    )
    .slice(0, limit);
};
